package com.shopsphere.controller;import com.shopsphere.model.Category;import com.shopsphere.repository.CategoryRepository;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/categories")public class CategoryController{private final CategoryRepository repo;public CategoryController(CategoryRepository r){repo=r;}@GetMapping public List<Category> all(){return repo.findAll();}@PostMapping @PreAuthorize("hasRole('ADMIN')")public Category create(@RequestBody Category c){return repo.save(c);}@PutMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")public Category update(@PathVariable Long id,@RequestBody Category c){Category x=repo.findById(id).orElseThrow();x.setName(c.getName());x.setDescription(c.getDescription());return repo.save(x);}@DeleteMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")public void delete(@PathVariable Long id){repo.deleteById(id);}}